/**
 * QueryPilot Hosted V1 API Client.
 *
 * Implements typed HTTP communication for the decoupled Hosted API V1 endpoints:
 * - POST /api/v1/generate-sql: Decoupled candidate SQL generation from client-supplied schema context.
 *   Never executes SQL or connects to customer databases.
 * - POST /api/v1/synthesize-answer: Privacy-preserving metadata-only answer synthesis.
 *   Never accepts or transmits row records or individual cell values.
 *
 * Security & Protocol Guarantees:
 * - Unexecuted Candidate SQL: Candidate SQL generated by /api/v1/generate-sql is strictly unexecuted
 *   and carries an explicit execution disclaimer.
 * - Privacy-Safe Synthesis: Synthesis requests send question text, candidate SQL, column names,
 *   row count, truncation flag, execution time, request ID, and the client-supplied execution status.
 *   Result rows, row data, passwords, and connection strings are strictly forbidden and rejected early.
 * - Client-Supplied Execution Status: The execution_status field is client-supplied metadata; it is
 *   not a verified cryptographic receipt of execution.
 * - URL Resolution: Resolves exact /api/v1/... paths relative to the configured hosted API base URL,
 *   supporting both local Vite proxying and split-origin production deployments.
 */

import {
  ACCESS_KEY_HEADER,
  getSessionAccessKey,
  type RequestOptions,
} from './apiClient.ts'
import {
  ApiClientError,
  type GenerateSQLRequest,
  type GenerateSQLResponse,
  type SynthesizeAnswerRequest,
  type SynthesizeAnswerResponse,
  type ValidationErrorDetail,
} from '../types/api.ts'
import { projectToModelFacingSchema } from './schemaProjection.ts'

export const V1_GENERATE_SQL_PATH = '/api/v1/generate-sql'
export const V1_SYNTHESIZE_ANSWER_PATH = '/api/v1/synthesize-answer'

/**
 * Resolves the configured Hosted API base URL.
 *
 * In local development with the Vite proxy, defaults to '' so that requests
 * target '/api/v1/...' on the same origin and are routed by the Vite proxy.
 * In split-origin deployments, a direct backend URL (e.g. 'http://127.0.0.1:8000')
 * can be provided via the VITE_API_BASE_URL environment variable.
 *
 * @throws ApiClientError if VITE_API_BASE_URL is explicitly configured with an invalid URL.
 */
export function getV1ApiBaseUrl(customEnvUrl?: string): string {
  const envUrl =
    customEnvUrl !== undefined
      ? customEnvUrl
      : ((globalThis as unknown as { __TEST_VITE_API_BASE_URL__?: string }).__TEST_VITE_API_BASE_URL__ !== undefined
          ? (globalThis as unknown as { __TEST_VITE_API_BASE_URL__?: string }).__TEST_VITE_API_BASE_URL__
          : (import.meta as { env?: Record<string, string | undefined> })?.env?.VITE_API_BASE_URL)

  if (envUrl === undefined || envUrl === null) {
    return ''
  }

  const trimmed = envUrl.trim()
  if (trimmed === '' || trimmed === '/api') {
    return ''
  }

  // Handle relative root or proxy path
  if (trimmed.startsWith('/')) {
    const cleanRelative = trimmed.replace(/\/+$/, '')
    return cleanRelative === '/api' ? '' : cleanRelative
  }

  // Handle absolute HTTP/HTTPS URL
  if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
    try {
      const parsed = new URL(trimmed)
      if (!parsed.hostname) {
        throw new Error('Missing hostname')
      }
      return trimmed.replace(/\/+$/, '')
    } catch {
      throw new ApiClientError({
        message: `Invalid VITE_API_BASE_URL configured: "${envUrl}". Must be a valid absolute HTTP or HTTPS URL.`,
        kind: 'network',
      })
    }
  }

  throw new ApiClientError({
    message: `Invalid VITE_API_BASE_URL configured: "${envUrl}". Expected an absolute HTTP/HTTPS URL or a relative path starting with "/".`,
    kind: 'network',
  })
}

/**
 * Resolves the full request URL for a hosted V1 API endpoint.
 *
 * Guarantees that the path preserves the '/api/v1' prefix without accidental duplication.
 *
 * @param path - Target endpoint path (e.g. '/api/v1/generate-sql' or '/generate-sql').
 * @param customEnvUrl - Optional override for testing or dynamic configuration.
 */
export function resolveV1Endpoint(path: string, customEnvUrl?: string): string {
  const base = getV1ApiBaseUrl(customEnvUrl)
  let cleanPath = path.startsWith('/') ? path : `/${path}`

  if (!cleanPath.startsWith('/api/v1/')) {
    cleanPath = cleanPath.startsWith('/v1/')
      ? `/api${cleanPath}`
      : `/api/v1${cleanPath}`
  }

  return `${base}${cleanPath}`
}

/**
 * Sanitizes potentially sensitive details (passwords, tokens, bearer keys) from error messages.
 */
function sanitizeErrorMessage(rawMessage: string): string {
  if (!rawMessage) {
    return ''
  }
  return rawMessage
    .replace(/(?:password|pwd|secret|token)\s*=\s*[^;\s&]+/gi, '$1=[REDACTED]')
    .replace(/(?:Bearer\s+)[A-Za-z0-9._~+/-]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\r?\n+/g, ' ')
    .trim()
}

/**
 * Internal helper executing fetch with standardized headers, correlation IDs, and error classification.
 */
async function sendV1Request<T>(
  url: string,
  bodyObj: unknown,
  options?: RequestOptions
): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  }

  const effectiveRequestId = options?.requestId?.trim()
  if (effectiveRequestId) {
    headers['X-Request-ID'] = effectiveRequestId
  }

  const effectiveKey = options?.accessKey?.trim() || getSessionAccessKey()
  if (effectiveKey) {
    headers[ACCESS_KEY_HEADER] = effectiveKey
  }

  let response: Response
  try {
    response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(bodyObj),
      signal: options?.signal,
    })
  } catch (err: unknown) {
    if (err instanceof DOMException && err.name === 'AbortError') {
      throw err
    }
    throw new ApiClientError({
      message: 'Failed to connect to QueryPilot Hosted API. Please check your network connection.',
      kind: 'network',
      requestId: effectiveRequestId || null,
    })
  }

  const responseRequestId = response.headers.get('x-request-id') || effectiveRequestId || null

  let responseText = ''
  try {
    responseText = await response.text()
  } catch {
    responseText = ''
  }

  let parsedJson: Record<string, unknown> | null = null
  if (responseText.trim()) {
    try {
      parsedJson = JSON.parse(responseText) as Record<string, unknown>
    } catch {
      parsedJson = null
    }
  }

  if (!response.ok) {
    let errorMessage = ''
    let validationErrors: ValidationErrorDetail[] | undefined

    if (parsedJson && typeof parsedJson === 'object') {
      if (typeof parsedJson.detail === 'string' && parsedJson.detail.trim()) {
        errorMessage = sanitizeErrorMessage(parsedJson.detail.trim())
      } else if (Array.isArray(parsedJson.detail)) {
        validationErrors = parsedJson.detail as ValidationErrorDetail[]
        errorMessage = sanitizeErrorMessage(
          parsedJson.detail
            .map((d: unknown) => {
              if (d && typeof d === 'object' && 'msg' in d) {
                return String((d as { msg: unknown }).msg)
              }
              return 'Invalid request parameter'
            })
            .join('; ')
        )
      }
    }

    if (!errorMessage) {
      errorMessage = `Hosted API request failed with status HTTP ${response.status}.`
    }

    let kind: ApiClientError['kind'] = 'server'
    if (response.status === 400 || response.status === 422 || response.status === 413) {
      kind = 'validation'
    } else if (response.status === 401) {
      kind = 'unauthorized'
    } else if (response.status === 429) {
      kind = 'server'
    }

    throw new ApiClientError({
      message: errorMessage,
      kind,
      statusCode: response.status,
      requestId: responseRequestId,
      validationErrors,
    })
  }

  if (parsedJson === null) {
    throw new ApiClientError({
      message: `Invalid JSON response received from Hosted API (HTTP ${response.status}).`,
      kind: 'parse',
      statusCode: response.status,
      requestId: responseRequestId,
    })
  }

  return parsedJson as T
}

/**
 * Submits a natural-language question and model-facing schema context to the hosted API
 * for decoupled SQL generation.
 *
 * Security & Model Guarantees:
 * - Hosted API never connects to customer databases or executes queries.
 * - The returned candidate SQL is strictly an unexecuted candidate (status='generated').
 * - Handles statuses: 'generated', 'clarification_needed', 'unsupported', and 'generation_failed'.
 *
 * @param request - Validated GenerateSQLRequest.
 * @param options - Optional cancellation signal, correlation ID, or access key override.
 * @returns Promise resolving to GenerateSQLResponse.
 * @throws ApiClientError on validation error (422), unauthorized (401), rate limit (429), or server failure.
 */
export async function generateSql(
  request: GenerateSQLRequest,
  options?: RequestOptions
): Promise<GenerateSQLResponse> {
  if (!request || typeof request !== 'object') {
    throw new ApiClientError({
      message: 'Invalid request: payload must be a non-null object.',
      kind: 'validation',
    })
  }

  if (typeof request.question !== 'string' || !request.question.trim()) {
    throw new ApiClientError({
      message: 'Question cannot be empty or whitespace.',
      kind: 'validation',
    })
  }

  const trimmedQuestion = request.question.trim()
  if (trimmedQuestion.length > 1000) {
    throw new ApiClientError({
      message: `Question exceeds maximum length of 1000 characters (${trimmedQuestion.length} chars).`,
      kind: 'validation',
    })
  }

  if (!request.schema_context || typeof request.schema_context !== 'object') {
    throw new ApiClientError({
      message: 'schema_context must be provided as a non-null object.',
      kind: 'validation',
    })
  }

  // Ensure schema_context adheres to the strict ModelFacingSchemaContext contract
  const validatedSchemaContext = projectToModelFacingSchema(request.schema_context)

  const effectiveRequestId = request.request_id?.trim() || options?.requestId?.trim()
  const normalizedDiagnosticFeedback =
    typeof request.diagnostic_feedback === 'string' && request.diagnostic_feedback.trim()
      ? request.diagnostic_feedback.trim().slice(0, 500)
      : undefined

  const payload: GenerateSQLRequest = {
    question: trimmedQuestion,
    schema_context: validatedSchemaContext,
    ...(request.conversation_context && request.conversation_context.length > 0
      ? { conversation_context: request.conversation_context }
      : {}),
    ...(normalizedDiagnosticFeedback
      ? { diagnostic_feedback: normalizedDiagnosticFeedback }
      : {}),
    ...(effectiveRequestId ? { request_id: effectiveRequestId } : {}),
  }

  const url = resolveV1Endpoint(V1_GENERATE_SQL_PATH)
  return sendV1Request<GenerateSQLResponse>(url, payload, {
    ...options,
    requestId: effectiveRequestId,
  })
}

/**
 * Submits query execution metadata (column names, row count, timing) to the hosted API
 * for privacy-preserving natural language answer synthesis.
 *
 * Security & Privacy Guarantees:
 * - Outbound payload contains NO row records, cell values, database credentials, or connection strings.
 * - Column metadata contains column names only.
 * - The execution_status field is client-supplied metadata; it is NOT verified cryptographic proof of execution.
 *
 * @param request - Validated SynthesizeAnswerRequest.
 * @param options - Optional cancellation signal, correlation ID, or access key override.
 * @returns Promise resolving to SynthesizeAnswerResponse.
 * @throws ApiClientError on validation error (422), unauthorized (401), rate limit (429), or server failure.
 */
export async function synthesizeAnswer(
  request: SynthesizeAnswerRequest,
  options?: RequestOptions
): Promise<SynthesizeAnswerResponse> {
  if (!request || typeof request !== 'object') {
    throw new ApiClientError({
      message: 'Invalid request: payload must be a non-null object.',
      kind: 'validation',
    })
  }

  // 1. Strict Privacy Audit: verify no row data or credentials leaked in request
  const candidateRecord = request as unknown as Record<string, unknown>
  const forbiddenKeys = [
    'rows',
    'row_data',
    'data',
    'records',
    'password',
    'pwd',
    'secret',
    'token',
    'connection_string',
    'conn_str',
    'server',
    'database',
  ]
  for (const forbidden of forbiddenKeys) {
    if (forbidden in candidateRecord && candidateRecord[forbidden] !== undefined) {
      throw new ApiClientError({
        message: `Privacy violation: synthesis payload must not contain '${forbidden}'. Raw rows and credentials must remain local.`,
        kind: 'validation',
      })
    }
  }

  // 2. Validate question
  if (typeof request.question !== 'string' || !request.question.trim()) {
    throw new ApiClientError({
      message: 'Question cannot be empty or whitespace.',
      kind: 'validation',
    })
  }
  const trimmedQuestion = request.question.trim()
  if (trimmedQuestion.length > 1000) {
    throw new ApiClientError({
      message: `Question exceeds maximum length of 1000 characters (${trimmedQuestion.length} chars).`,
      kind: 'validation',
    })
  }

  // 3. Validate candidate_sql
  if (typeof request.candidate_sql !== 'string' || !request.candidate_sql.trim()) {
    throw new ApiClientError({
      message: 'candidate_sql cannot be empty or whitespace.',
      kind: 'validation',
    })
  }
  const trimmedSql = request.candidate_sql.trim()
  if (trimmedSql.length > 10000) {
    throw new ApiClientError({
      message: `candidate_sql exceeds maximum length of 10000 characters (${trimmedSql.length} chars).`,
      kind: 'validation',
    })
  }

  // 4. Validate columns: names only, 1-100 items
  if (!Array.isArray(request.columns) || request.columns.length === 0) {
    throw new ApiClientError({
      message: 'columns must be a non-empty array of column name strings.',
      kind: 'validation',
    })
  }
  if (request.columns.length > 100) {
    throw new ApiClientError({
      message: `columns array cannot exceed 100 items, received ${request.columns.length}.`,
      kind: 'validation',
    })
  }
  const cleanedColumns: string[] = []
  for (let idx = 0; idx < request.columns.length; idx++) {
    const col = request.columns[idx]
    if (typeof col !== 'string' || !col.trim()) {
      throw new ApiClientError({
        message: `Column at index ${idx} must be a non-empty string.`,
        kind: 'validation',
      })
    }
    const cleanCol = col.trim()
    if (cleanCol.length > 128) {
      throw new ApiClientError({
        message: `Column name '${cleanCol}' exceeds maximum length of 128 characters.`,
        kind: 'validation',
      })
    }
    cleanedColumns.push(cleanCol)
  }

  // 5. Validate row_count
  if (typeof request.row_count !== 'number' || !Number.isInteger(request.row_count) || request.row_count < 0) {
    throw new ApiClientError({
      message: 'row_count must be a non-negative integer.',
      kind: 'validation',
    })
  }
  if (request.row_count > 10000) {
    throw new ApiClientError({
      message: 'row_count cannot exceed 10000.',
      kind: 'validation',
    })
  }

  // 6. Validate execution_status: must be strictly 'succeeded'
  if (typeof request.execution_status !== 'string' || request.execution_status.trim().toLowerCase() !== 'succeeded') {
    throw new ApiClientError({
      message: "Answer synthesis requires execution_status to be 'succeeded'.",
      kind: 'validation',
    })
  }

  // 7. Validate execution_time_ms
  if (typeof request.execution_time_ms !== 'number' || request.execution_time_ms < 0 || request.execution_time_ms > 60000) {
    throw new ApiClientError({
      message: 'execution_time_ms must be a number between 0.0 and 60000.0 ms.',
      kind: 'validation',
    })
  }

  // 8. Validate request_id
  const effectiveRequestId = request.request_id?.trim() || options?.requestId?.trim()
  if (!effectiveRequestId) {
    throw new ApiClientError({
      message: 'request_id must be provided as a non-empty string.',
      kind: 'validation',
    })
  }

  const payload: SynthesizeAnswerRequest = {
    question: trimmedQuestion,
    candidate_sql: trimmedSql,
    columns: cleanedColumns,
    row_count: request.row_count,
    truncated: Boolean(request.truncated),
    execution_status: 'succeeded',
    execution_time_ms: request.execution_time_ms,
    request_id: effectiveRequestId,
  }

  const url = resolveV1Endpoint(V1_SYNTHESIZE_ANSWER_PATH)
  return sendV1Request<SynthesizeAnswerResponse>(url, payload, {
    ...options,
    requestId: effectiveRequestId,
  })
}
